function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 - 70, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 70, H/2);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 + 10*Math.sin(t), H/2 - 20 - 10*Math.cos(t));
  ctx.lineTo(W/2 + 40 + 10*Math.sin(t), H/2 - 40 - 10*Math.cos(t));
  ctx.lineTo(W/2 + 20 + 10*Math.sin(t), H/2 - 60 - 10*Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 - 10*Math.sin(t), H/2 - 20 + 10*Math.cos(t));
  ctx.lineTo(W/2 - 40 - 10*Math.sin(t), H/2 - 40 + 10*Math.cos(t));
  ctx.lineTo(W/2 - 20 - 10*Math.sin(t), H/2 - 60 + 10*Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 + 10*Math.sin(t + Math.PI/2), H/2 + 20 + 10*Math.cos(t + Math.PI/2));
  ctx.lineTo(W/2 + 40 + 10*Math.sin(t + Math.PI/2), H/2 + 40 + 10*Math.cos(t + Math.PI/2));
  ctx.lineTo(W/2 + 20 + 10*Math.sin(t + Math.PI/2), H/2 + 60 + 10*Math.cos(t + Math.PI/2));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 - 10*Math.sin(t + Math.PI/2), H/2 + 20 - 10*Math.cos(t + Math.PI/2));
  ctx.lineTo(W/2 - 40 - 10*Math.sin(t + Math.PI/2), H/2 + 40 - 10*Math.cos(t + Math.PI/2));
  ctx.lineTo(W/2 - 20 - 10*Math.sin(t + Math.PI/2), H/2 + 60 - 10*Math.cos(t + Math.PI/2));
  ctx.stroke();
  ctx.restore();
}
